package nativeshim

import (
	"bytes"
	"encoding/json"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"
)

// generatedFiles lists the generated files under a shim directory and its
// prebuilt root, relative to the pair, so checked-in and fresh trees compare.
func generatedFiles(t *testing.T, shim, prebuilt string) map[string]string {
	t.Helper()
	files := map[string]string{"shim/prebuilt_backend.go": filepath.Join(shim, "prebuilt_backend.go")}
	err := filepath.WalkDir(prebuilt, func(path string, entry fs.DirEntry, err error) error {
		if err != nil || entry.IsDir() {
			return err
		}
		source, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		// prebuilt/doc.go is maintained by hand.
		if bytes.HasPrefix(source, []byte("// Code generated by gen.go")) {
			relative, err := filepath.Rel(prebuilt, path)
			if err != nil {
				return err
			}
			files["prebuilt/"+filepath.ToSlash(relative)] = path
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return files
}

// Regenerate into scratch space: a stale table or registration package would
// otherwise only fail on the affected target, in a build that needs its module.
func TestGeneratedFilesAreCurrent(t *testing.T) {
	out := t.TempDir()
	prebuilt := filepath.Join(out, "prebuilt")
	if output, err := exec.Command("go", "run", "gen.go", "-o", out, "-prebuilt", prebuilt).CombinedOutput(); err != nil {
		t.Fatalf("generate: %v\n%s", err, output)
	}
	want := generatedFiles(t, out, prebuilt)
	got := generatedFiles(t, ".", "../../prebuilt")
	var names []string
	for name := range want {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		expected, err := os.ReadFile(want[name])
		if err != nil {
			t.Fatal(err)
		}
		actual, err := os.ReadFile(got[name])
		if err != nil {
			t.Errorf("%v; run make generate-nativeshim", err)
			continue
		}
		if !bytes.Equal(actual, expected) {
			t.Errorf("%s is stale; run make generate-nativeshim", name)
		}
	}
	for name := range got {
		if _, ok := want[name]; !ok {
			t.Errorf("%s is no longer generated; remove it", name)
		}
	}
	if stale, _ := filepath.Glob("prebuilt_*_*.go"); len(stale) != 0 {
		t.Errorf("per-target proxies %v must not import native modules into the shim", stale)
	}
}

// Every manifest function must be registered, and every target must register
// its own module rather than a neighbor copied by mistake.
func TestRegistrationsUseOwnTarget(t *testing.T) {
	var bindings struct{ Functions []struct{ Name string } }
	var table struct {
		ModulePrefix string
		Targets      []struct{ Go string }
	}
	for path, value := range map[string]any{"../../dist/native-bindings.json": &bindings, "../../dist/native-targets.json": &table} {
		data, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(data, value); err != nil {
			t.Fatal(err)
		}
	}
	if len(table.Targets) == 0 {
		t.Fatal("no native targets")
	}
	for _, target := range table.Targets {
		path := filepath.Join("../../prebuilt", filepath.FromSlash(target.Go), "register.go")
		source, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		text := string(source)
		goos, goarch, _ := strings.Cut(target.Go, "/")
		if !strings.Contains(text, "//go:build gpui_prebuilt && "+goos+" && "+goarch+"\n") {
			t.Errorf("%s is not constrained to %s", path, target.Go)
		}
		if !strings.Contains(text, `native "`+table.ModulePrefix+"/"+target.Go+`"`) {
			t.Errorf("%s does not import the %s module", path, target.Go)
		}
		if !strings.Contains(text, `nativeshim.Register("`+target.Go+`"`) {
			t.Errorf("%s does not register as %s", path, target.Go)
		}
		for _, fn := range append(bindings.Functions, struct{ Name string }{tlsFinalize}) {
			if !regexp.MustCompile(`(?m)^\s+` + fn.Name + `:\s+native\.` + fn.Name + `,$`).MatchString(text) {
				t.Errorf("%s does not register %s", path, fn.Name)
			}
		}
	}
}

// Named here as well as in gen.go, which is excluded from the test build.
const tlsFinalize = "TLSFinalizeCurrentThread"
